CREATE TYPE public.app_role AS ENUM ('organizer');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.announcements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id text NOT NULL, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 4000), priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('normal','urgent')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.announcements TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.announcements TO authenticated;
GRANT ALL ON public.announcements TO service_role;
ALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public announcements" ON public.announcements FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Organizers manage announcements" ON public.announcements FOR ALL TO authenticated USING(public.has_role(auth.uid(),'organizer')) WITH CHECK(public.has_role(auth.uid(),'organizer'));
CREATE TABLE public.imported_matches (id text PRIMARY KEY, event_id text NOT NULL, match_data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.imported_matches TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.imported_matches TO authenticated;
GRANT ALL ON public.imported_matches TO service_role;
ALTER TABLE public.imported_matches ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public matches" ON public.imported_matches FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Organizers manage matches" ON public.imported_matches FOR ALL TO authenticated USING(public.has_role(auth.uid(),'organizer')) WITH CHECK(public.has_role(auth.uid(),'organizer'));
CREATE TABLE public.team_follows (user_id uuid NOT NULL, team_id text NOT NULL, PRIMARY KEY(user_id,team_id));
GRANT SELECT,INSERT,DELETE ON public.team_follows TO authenticated;
GRANT ALL ON public.team_follows TO service_role;
ALTER TABLE public.team_follows ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own follows" ON public.team_follows FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "Add own follows" ON public.team_follows FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY "Remove own follows" ON public.team_follows FOR DELETE TO authenticated USING(user_id=auth.uid());